import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

// These hooks are gone from hooks.json and src/hooks, but the hand-written docs
// kept describing them as live, while hooks/memory-hooks.mdx said they were
// removed. A reader got both answers (#2735).
const REMOVED = [
	"memory-context",
	"memory-writer",
	"auto-remember-continuity",
	"memory-bridge",
	"graph-queue-sync",
] as const;

const ROOT = path.join(process.cwd(), "content/docs");

// The two pages whose job is to say these hooks are gone.
const STATES_REMOVAL = new Set([
	"hooks/memory-hooks.mdx",
	"memory/local-memory.mdx",
]);

function pages(dir: string): string[] {
	return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
		const full = path.join(dir, entry.name);
		if (entry.isDirectory()) return pages(full);
		return entry.name.endsWith(".mdx") ? [full] : [];
	});
}

// reference/ is generated from src/, where these names appear as worked examples.
const handWritten = pages(ROOT)
	.map((file) => path.relative(ROOT, file))
	.filter((file) => !file.startsWith("reference/"))
	.filter((file) => !STATES_REMOVAL.has(file));

describe("hand-written docs do not describe removed memory hooks", () => {
	it("scans the hand-written pages", () => {
		expect(handWritten.length).toBeGreaterThan(50);
		expect(handWritten).toContain("memory/overview.mdx");
	});

	it.each(REMOVED)("%s is gone", (name) => {
		const hits = handWritten.flatMap((file) =>
			readFileSync(path.join(ROOT, file), "utf8")
				.split("\n")
				.flatMap((line, i) =>
					line.includes(name) ? [`${file}:${i + 1}`] : [],
				),
		);
		expect(hits).toEqual([]);
	});

	// No code holds a 0.7 threshold and no hook writes MEMORY.md. These pages
	// described a scored promotion step that does not exist.
	it("does not describe a scored promotion to MEMORY.md", () => {
		const hits = handWritten.filter((file) =>
			/auto-?promot|confidence >= 0\.7|score 0\.7|0\.7 confidence|high-confidence decisions/i.test(
				readFileSync(path.join(ROOT, file), "utf8"),
			),
		);
		expect(hits).toEqual([]);
	});

	it("does not credit a memory writer", () => {
		const hits = handWritten.filter((file) =>
			/\bthe memory writer\b/i.test(
				readFileSync(path.join(ROOT, file), "utf8"),
			),
		);
		expect(hits).toEqual([]);
	});
});
